function flangerProcess(samples, sr, opts){
  opts = opts || {};
  var rate = opts.rate || 0.3;        // LFO Hz
  var depthMs = opts.depthMs != null ? opts.depthMs : 5; // 最大延迟 ms
  var mix = opts.mix != null ? opts.mix : 0.5;
  var fb = opts.feedback != null ? opts.feedback : 0.4;
  var n = samples.length;
  var out = new Array(n);
  var delayBuf = new Array(Math.ceil(sr*depthMs/1000)+2).fill(0);
  var w = 2*Math.PI*rate/sr;
  var ph = 0, wp = 0;
  for(var i=0;i<n;i++){
    ph += w; if(ph>2*Math.PI) ph-=2*Math.PI;
    var frac = (Math.sin(ph)*0.5+0.5); // 0..1
    var dSamples = frac * (sr*depthMs/1000);
    var di = Math.floor(dSamples);
    var df = dSamples - di;
    var idx0 = wp - di, idx1 = wp - di - 1;
    function rd(buf, k){ k = ((k % buf.length)+buf.length)%buf.length; return buf[k]; }
    var delayed = rd(delayBuf, idx0)*(1-df) + rd(delayBuf, idx1)*df;
    var x = samples[i];
    var wet = x + fb*delayed;
    delayBuf[wp] = wet;
    wp = (wp+1)%delayBuf.length;
    out[i] = x*(1-mix) + delayed*mix;
  }
  return out;
}
function flangerAnalyze(samples, sr, opts){
  var out = flangerProcess(samples, sr, opts);
  var peak=0,sum=0;
  for(var i=0;i<out.length;i++){ var a=Math.abs(out[i]); if(a>peak)peak=a; sum+=out[i]*out[i]; }
  return { length:out.length, peak:peak, rms:Math.sqrt(sum/out.length) };
}

var EXPORTS={flangerProcess:flangerProcess,flangerAnalyze:flangerAnalyze};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FlangerForgePure = EXPORTS; }
